/**
 * Test flow for createCatalogTask action
 * Demonstrates creating a catalog task
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCreateCatalogTask = Flow(
    {
        $id: Now.ID['test_create_catalog_task_flow'],
        name: 'Test Create Catalog Task',
        description: 'Tests the createCatalogTask core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_create_catalog_task_trigger'] },
        {
            table: 'sc_req_item',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (params) => {
        const result = wfa.action(
            action.core.createCatalogTask,
            { $id: Now.ID['test_create_catalog_task_action'] },
            {
                ah_requested_item: params.trigger.current.sys_id,
                ah_short_description: 'Test catalog task',
                ah_fields: 'assignment_group=IT Support',
                ah_wait: false,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_create_catalog_task_log'] },
            {
                log_level: 'info',
                log_message: `createCatalogTask outputs: Catalog Task=${(result as any)['Catalog Task']}`,
            }
        )
    }
)
